import { createCoreFailureEnvelope, createPublicCoreErrorDto } from "@codex-provider-sync/contracts";
import { TransportCoreClient } from "./client.js";
export const DESKTOP_READ_METHODS = Object.freeze([
    "getStatus",
    "listBackups",
    "listHistory",
    "getHistorySession",
    "getDiagnostics"
]);
const DESKTOP_READ_METHOD_SET = new Set(DESKTOP_READ_METHODS);
export function isDesktopReadMethod(method) {
    return DESKTOP_READ_METHOD_SET.has(method);
}
class DesktopCoreTransport {
    #bridge;
    constructor(bridge) {
        this.#bridge = bridge;
    }
    async request(envelope, options = {}) {
        if (!isDesktopReadMethod(envelope.method)) {
            return createCoreFailureEnvelope(envelope, createPublicCoreErrorDto("PERMISSION_DENIED"));
        }
        if (options.signal?.aborted) {
            throw new DOMException("The desktop Core request was cancelled.", "AbortError");
        }
        const request = this.#bridge.requestReadOnly(envelope);
        if (!options.signal)
            return request;
        return new Promise((resolve, reject) => {
            const onAbort = () => reject(new DOMException("The desktop Core request was cancelled.", "AbortError"));
            options.signal?.addEventListener("abort", onAbort, { once: true });
            void request.then(resolve, reject).finally(() => {
                options.signal?.removeEventListener("abort", onAbort);
            });
        });
    }
}
export class DesktopCoreClient extends TransportCoreClient {
    constructor(bridge, { requestIdFactory } = {}) {
        super(new DesktopCoreTransport(bridge), { requestIdFactory });
    }
}
